public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }
    int count = 0;
    int year = Y;
    while (true) {
        if ((year % 400 == 0) || (year % 4 == 0 && year % 100 != 0)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }
}

public static int calculateTimeNeeded(int N) {
    // The required time is zero for less than three people,
    // otherwise it follows the pattern 2,4,6 for N=4,5,6 respectively.
    if (N < 3) {
        return 0;
    }
    // Time needed grows linearly with N: time = 2 * (N - 3)
    return 2 * (N - 3);
}

