    for (int i=0;i<n;i++) adj[i] = new ArrayList<>();
    for (int[] e : edges) {
        int u=e[0], v=e[1];
        adj[u].add(v);
        adj[v].add(u);
    }
    boolean[] visited = new boolean[n];
    int total = dfs(0, adj, hasApple, visited);
    return total;
}

private int dfs(int node, List<Integer>[] adj, boolean[] hasApple, boolean[] visited) {
    visited[node]=true;
    int time = 0;
    for (int nei : adj[node]) {
        if (!visited[nei]) {
            int childTime = dfs(nei, adj, hasApple, visited);
            if (childTime > 0 || hasApple[nei]) {
                time += childTime + 2;
            }
        }
    }
    return time;
}

